/**
 * World Plaza — UI CHROME localization (LOCALIZATION_SCALE §2).
 *
 * THE ONE STRING SEAM every chrome surface reads. The entire UI chrome (welcome,
 * language chooser, onboarding, menu, status capsule, quest section, quest-
 * complete interlude, toasts) renders in the learner's NATIVE language — the
 * language they KNOW (`learnerPair.native`, i.e. the stack's `languages[0]`).
 * The orchestrator threads that native locale to every surface; surfaces resolve
 * each string via `t(key, native, params)`.
 *
 * This mirrors the proven repo pattern verbatim (tutomaton `src/i18n.ts` +
 * `tools/gen_i18n.py`, also pronunciation-coach): an English source-of-truth
 * dict (`en`), a `GENERATED_LOCALES` block filled by `tools/gen_i18n.py` (OpenAI),
 * and a `t(key, lang, params)` resolver that collapses variants
 * (ko-polite→ko, pt-BR→pt, zh-Hans→zh) and falls back PER-KEY to English so a
 * missing/partial locale never shows a blank — it shows clean English.
 *
 * The committed `GENERATED_LOCALES` is the offline floor (~tens of KB of code,
 * well under any budget — it is code, not localStorage). A future CDN string-pack
 * can merge OVER it at mount (per LOCALIZATION_SCALE §2.2), but that is not wired
 * here; the committed table stands alone.
 *
 * RTL: `isRtl(lang)` + `applyDir(root, lang)` orient the WHOLE pack root to RTL
 * when the native is a right-to-left script (Arabic, Hebrew, Farsi, Urdu). The
 * chrome CSS uses logical properties so a single `dir="rtl"` mirrors it.
 */

/* ============================================================ key union ===== */

export type I18nKey =
  // ── welcome (surfaces.ts showWelcome) ──────────────────────────────────────
  | "welcome.eyebrow"
  | "welcome.titleNamed" // "Good morning, {name}"
  | "welcome.title" // no-name fallback
  | "welcome.sub"
  | "welcome.you.title"
  | "welcome.you.bodyNamed" // "Your paper self, {name}, is dressed and ready."
  | "welcome.you.body"
  | "welcome.where.title"
  | "welcome.where.body" // "{place} — harbor, market, bridges and back-streets."
  | "welcome.goal.title"
  | "welcome.goal.body" // "Pick up {lang} as you go — gentle, one exchange at a time."
  | "welcome.practice.title"
  | "welcome.practice.body" // "Live entirely in {lang} — everyone speaks it; no translations."
  | "welcome.cta"
  // ── language chooser (surfaces.ts showLanguageChooser) ──────────────────────
  | "chooser.eyebrow"
  | "chooser.title"
  | "chooser.sub"
  | "chooser.playIn" // aria: "Play in {lang}"
  // ── onboarding (onboarding.ts) ──────────────────────────────────────────────
  | "onb.skip"
  | "onb.skipAria"
  | "onb.welcome.title"
  | "onb.welcome.sub"
  | "onb.welcome.begin"
  | "onb.name.title"
  | "onb.name.sub"
  | "onb.name.reroll"
  | "onb.name.use"
  | "onb.dress.title"
  | "onb.dress.subNamed" // "You'll enter as {name}."
  | "onb.dress.color"
  | "onb.dress.outfit"
  | "onb.dress.hat"
  | "onb.dress.hatColor"
  | "onb.dress.accessory"
  | "onb.dress.accessoryColor"
  | "onb.dress.skin"
  | "onb.dress.enter"
  // ── menu panel (shell/menuPanel.ts) ─────────────────────────────────────────
  | "menu.title"
  | "menu.resume"
  | "menu.leave"
  | "menu.close"
  | "menu.tab.map"
  | "menu.tab.inventory"
  | "menu.tab.quest"
  | "menu.tab.badges"
  | "menu.comingSoon"
  // ── status capsule / quest tracker (quest/questTracker.ts) ──────────────────
  | "tracker.questLabel"
  | "tracker.findItem" // "Find {item}"
  | "tracker.deliverItem" // "Bring {item} to {who}"
  | "tracker.talkTo" // "→ talk to {who}"
  | "tracker.beginChallenge" // "Begin the challenge with {who}"
  | "tracker.progress" // "Step {done} of {total}"
  | "tracker.complete"
  | "tracker.details"
  | "tracker.collapse"
  | "tracker.immersion" // "Immersion: {level}"
  | "tracker.openQuest"
  | "tracker.openWallet"
  | "tracker.openBadges"
  | "tracker.location"
  // ── quest section (quest/questSection.ts) ───────────────────────────────────
  | "section.objectiveHeading"
  | "section.stepsHeading"
  | "section.findItem" // "Find {item}"
  | "section.deliverItem" // "Bring {item} to {who}"
  | "section.talkTo" // "Talk to {who}"
  | "section.progress" // "Step {done} of {total}"
  | "section.complete"
  // ── quest-complete interlude (vignettes/questInterlude.ts) ──────────────────
  | "interlude.title"
  | "interlude.subtitle" // "You finished “{quest}”."
  | "interlude.pickPrompt"
  | "interlude.goTo" // "Go to {where}"
  | "interlude.begin"
  | "interlude.notNow"
  // ── place tag (shell/placeTag.ts) ───────────────────────────────────────────
  | "placetag.online" // "{n} online"
  | "placetag.presenceAria" // "{n} players nearby"
  // ── immersion toggle (immersion/immersionToggle.ts) ─────────────────────────
  | "immersion.toggle.label"
  | "immersion.toggle.off"
  | "immersion.toggle.on"
  | "immersion.toggle.subOff"
  | "immersion.toggle.subOn"
  // ── quest-switch picker (quest/questSection.ts) ─────────────────────────────
  | "section.switchHeading"
  | "section.switchHint"
  | "section.currentBadge"
  | "section.goTo" // "Go to {where}"
  // ── challenge in-card instructions (challenges/tools/strings.ts) ────────────
  // The UI strings rendered INSIDE a micro-challenge card, in the UI locale
  // (native, or target under immersion). `{token}` for the interpolated ones.
  | "challenge.tapToContinue"
  | "challenge.hearIt"
  | "challenge.replay"
  | "challenge.tapInOrder"
  | "challenge.tapWordsInOrder"
  | "challenge.memoryFind"
  | "challenge.memoryStudy"
  | "challenge.sortPrompt"
  | "challenge.sortHint" // "🧺 {label}"
  | "challenge.pictureMatchHint"
  | "challenge.pictureMatchWordHint" // "Tap the word that means “{native}”"
  | "challenge.memorizeTitle"
  | "challenge.memorizeSub"
  | "challenge.ready"
  | "challenge.whichMeant" // "Which line meant “{native}”?"
  | "challenge.findHidden"
  | "challenge.unscramble"
  | "challenge.meansHint" // "as in “{native}”"
  | "challenge.buildOrder"
  | "challenge.whichFits"
  | "challenge.missingLine"
  | "challenge.chooseReply"
  | "challenge.whichTypo"
  | "challenge.whichRhymes" // "Which word rhymes with “{word}”?"
  | "challenge.verbHint" // "verb: {inf}"
  | "challenge.whichTranslation"
  | "challenge.tapMeaning"
  | "challenge.whichHeard"
  | "challenge.tapSpeakerReplay"
  | "challenge.trueLabel"
  | "challenge.falseLabel"
  | "challenge.oddOneOut"
  | "challenge.tapNumber"
  | "challenge.readItAloud"
  | "challenge.selfRateHint"
  | "challenge.sayItBack"
  | "challenge.listeningStop"
  | "challenge.scoring"
  | "challenge.heard" // "Heard: “{transcript}”"
  | "challenge.rateTough"
  | "challenge.rateOkay"
  | "challenge.rateNailed"

export type Dict = Record<I18nKey, string>

